/// Literal shapes that once made error-severity rules fire on code that compiles.
/// Every method here is a minimal reproduction of a measured false positive; the
/// sweep must stay silent on all of them.
public class FixtureLiteralShapes
{
}

Method.Source:
/// FN001 counted the comma INSIDE the literal as a fourth argument.
public int singleQuotedCommaArgument(str _text)
{
    return strFind(_text, ',', 1, strLen(_text));
}

/// CS001 read the '??' inside this mask as the C# null-coalescing operator.
public boolean guidMaskLiteral(str _candidate)
{
    return match('????????-????-????-????-????????????', _candidate);
}

/// SEL007 read the SQL inside this literal as an attempt at X++ join syntax.
public str sqlTextInLiteral()
{
    return ' LEFT JOIN %2 T2 ON T1.RECID = T2.RECID';
}

/// Lexer conformance: verbatim strings, doubled quotes, backslash escapes and
/// a block-comment marker inside a literal must all mask cleanly.
public container verbatimAndEscapes()
{
    str path = @'C:\Temp\report.pdf';
    str quoted = 'it''s here';
    str escaped = "line\nbreak \"quoted\"";
    str notAComment = 'this /* is not */ a comment';
    str macroText = 'the #define directive is text here';
    return [path, quoted, escaped, notAComment, macroText];
}

/// lintXppSelect flagged the joined table's own where clause. It is standard
/// X++: each join segment carries its own where.
public void whereAfterJoinIsLegal()
{
    CustTable    custTable;
    CustGroup    custGroup;

    while select custTable
        order by AccountNum
        join custGroup
            where custGroup.CustGroup == custTable.CustGroup
               && custGroup.Name != ''
    {
        info(custTable.AccountNum);
    }
}
